const r = $('Router').first().json;
let ev = {};
try { ev = $('Evaluer la correspondance').first().json || {}; } catch (e) {}
const t = Object.assign({}, r.todoist_rattacher);
const raison = ev.match
  ? 'Client trouvé (' + ev.client_nom + ') mais la note n\'a pas pu être consignée dans Interfast.'
  : 'Pas de correspondance unique dans Interfast. Candidats : ' + (ev.candidats || 'aucun') + '.';
t.description = r.note_crm + '\n\nClient dicté : "' + r.client + '". ' + raison + '\nCopier la note sur la bonne fiche client, puis cocher.';
const message = (ev.match ? 'Interfast indisponible' : 'Client "' + r.client + '" introuvable dans Interfast') + '\nTâche à rattacher > ' + r.dest_rattacher;
return [{ json: { todoist: t, message } }];

// Suggere le client Interfast le plus proche du lieu du memo (moins de 200 m)
const r = JSON.parse(JSON.stringify($('Router').first().json));
const p = $('Preparer').first().json;
const RAYON = 200;
let lat = null, lon = null;
if (p.lat && p.lon) { lat = Number(p.lat); lon = Number(p.lon); }
else {
  try {
    const f = (($('Geocoder le lieu').first().json || {}).features || [])[0];
    if (f && (f.properties.score || 0) >= 0.5) { lon = f.geometry.coordinates[0]; lat = f.geometry.coordinates[1]; }
  } catch (e) {}
}
// Pas de suggestion : client deja dicte, perso/holding, domicile ou depot, ou lieu inconnu
const chezSoi = /impasse du moulin|chemin de dandon/i.test(p.lieu || '');
if (r.client || ['PERSO', 'HOLDING'].includes(r.domaine) || chezSoi || lat === null) return [{ json: r }];
const rad = x => x * Math.PI / 180;
const dist = (a, b, c, d) => { const R = 6371000, dl = rad(c - a), dn = rad(d - b); const h = Math.sin(dl / 2) ** 2 + Math.cos(rad(a)) * Math.cos(rad(c)) * Math.sin(dn / 2) ** 2; return 2 * R * Math.asin(Math.sqrt(h)); };
const proches = $input.all().map(i => i.json)
  .filter(c => c && c.lat !== null && c.lat !== undefined && (c.score || 0) >= 0.5)
  .map(c => ({ nom: c.nom, ref: c.ref, id: c.client_id, m: Math.round(dist(lat, lon, Number(c.lat), Number(c.lon))) }))
  .filter(c => c.m <= RAYON)
  .sort((a, b) => a.m - b.m)
  .slice(0, 2);
if (!proches.length) return [{ json: r }];
const c0 = proches[0];
const autre = proches[1] ? ' Autre fiche proche : ' + proches[1].nom + ' (' + proches[1].ref + ', ' + proches[1].m + ' m).' : '';
r.client_proche = c0.nom;
r.todoist.content = r.todoist.content + ' - ' + c0.nom + ' ?';
r.todoist.description = 'Client à proximité au moment du mémo : ' + c0.nom + ' (' + c0.ref + ', ' + c0.m + ' m). À confirmer.' + autre + '\n\n' + r.todoist.description;
r.todoist.labels = (r.todoist.labels || []).concat(['client-proche']);
r.message = r.message + '\nPrès de : ' + c0.nom + ' (' + c0.m + ' m) ?';
return [{ json: r }];

const r = $('Router').first().json;
const res = $input.first().json || {};
const all = Array.isArray(res.items) ? res.items : [];
const items = all.filter(c => String(c.reference || '').toUpperCase().startsWith('C') && String(c.category || 'client') !== 'supplier');
const n = s => String(s || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
let cands = items;
if (cands.length > 1) {
  const cible = n(r.client);
  const ex = cands.filter(c => n(c.name) === cible || n(c.name).split(/\s+/).includes(cible));
  if (ex.length) cands = ex;
}
const match = cands.length === 1 ? cands[0] : null;
return [{ json: {
  match: !!match,
  client_id: match ? String(match.id) : '',
  client_nom: match ? String(match.name || '').trim() : '',
  candidats: items.length ? items.slice(0, 5).map(c => String(c.name || '').trim() + ' (' + c.reference + ')').join(', ') : 'aucun'
} }];

// Film a voir dicte par Laurent -> Perso / Films a voir, titre = nom du film seul
const r = JSON.parse(JSON.stringify($input.first().json));
const p = $('Preparer').first().json;
const texte = String(p.note || '');
const estFilm = /(liste|list)\s+(de|des)?\s*films?|films?\s+(a|à)\s+(voir|regarder)|(regarder|voir)\s+(le\s+)?film/i.test(texte);
if (!estFilm || p.auteur !== 'laurent' || r.action !== 'todoist' || !r.todoist) return [{ json: r }];
let t = String(r.titre || texte);
t = t.replace(/^(info|idée|idee|à trier|a trier)\s*:\s*/i, '')
  .replace(/^(ajouter|noter|regarder|voir)\s+(le\s+film\s+)?/i, '')
  .replace(/^film\s+/i, '')
  .replace(/\s+(à|a|dans)\s+(la|ma|mon)\s+(liste|film).*$/i, '')
  .replace(/^[«"\s]+|[»"\s]+$/g, '')
  .trim();
if (!t) t = String(r.titre || texte);
t = t.charAt(0).toUpperCase() + t.slice(1);
const td = r.todoist;
td.content = t;
td.project_id = '6hh423vGr88f287j';
td.section_id = '6hjQhj2hr8ff5wGC';
td.labels = [...new Set(['memo', 'film'].concat((td.labels || []).filter(l => !['a-trier', 'pro-ou-perso', 'client-proche', 'commande', 'devis'].includes(l))))];
delete td.due_date;
r.message = 'Film > Perso / Films à voir\n' + t;
return [{ json: r }];

// Complete le prompt de Preparer : le materiel manquant est une COMMANDE, meme dit en trois mots
// + la cle objet (icone du memo), en reutilisant les icones deja presentes dans la banque
const p = JSON.parse(JSON.stringify($('Preparer').first().json));
const dispo = [];
try {
  for (const it of $input.all()) {
    const nom = String((it.json || {}).nom || '');
    if (nom.startsWith('icones/')) dispo.push(nom.slice(7).replace(/\.[a-z0-9]+$/i, ''));
  }
} catch (e) {}
const ajout = [
  `Précision sur le theme COMMANDE : tout matériel, outillage, consommable ou pièce qui manque ou qu'il faut prendre, commander, acheter ou récupérer, même sans le mot commander ("il manque", "il n'y a plus de", "on n'a plus de", "il faut une pince coupante", "plus de Colson").`,
  `Dans ce cas : type TACHE, domaine EQUIPE, theme COMMANDE, titre = l'article avec la quantité ou la marque si elles sont dites, sans verbe (exemples : "Colson", "Pince coupante", "2 bobines de câble 3G1,5"), et confiance HAUTE même si le mémo est très court. Une demande de matériel n'est jamais un DEVIS.`,
  `Ajoute toujours la clé perso_possible : true si le mémo pourrait aussi bien être personnel (maison, famille, courses, bricolage à la maison) parce que rien ne le relie clairement à ClimatPro (ni client, ni chantier, ni technicien, ni fournisseur, ni dépôt, ni camion, ni matériel de clim). Exemples : "acheter des piles" = true, "acheter du scotch" = true, "plus de Colson" = false, "acheter des piles pour la télécommande de Mme Martin" = false, "acheter du papier toilette" = false si tu le ranges déjà en PERSO. Sinon false.`,
  `Ajoute toujours la clé objet : l'objet physique principal du mémo, pour choisir son icône. Un seul nom commun, au singulier, en minuscules, sans accent, sans article, sans espace (un tiret entre deux mots : "bouteille-fluide", "pompe-a-vide"). Exemples : "prendre le balai pour demain" = "balai", "il n'y a plus de goulottes" = "goulotte", "changer les filtres chez Mme Martin" = "filtre", "acheter deux échelles" = "echelle". Si le mémo n'a pas d'objet concret (relancer quelqu'un, une idée, un rendez-vous, une facture à faire), mets null.`
  + (dispo.length ? ` Icônes déjà disponibles, à réutiliser telles quelles quand l'objet correspond ou est très proche (synonyme, même famille) : ${dispo.sort().join(', ')}.` : '')
].join('\n');
p.requete.system = p.requete.system + '\n' + ajout;
return [{ json: p }];

const b = ($input.first().json.body) || {};
const note = String(b.note || '').trim();
const appareil = String(b.appareil || '').trim();
// Appareils de Laurent. Tout autre iPhone est considere comme l'equipe (Equipe ClimatPro uniquement).
const APPAREILS_LAURENT = ['iphone klb'];
const auteur = APPAREILS_LAURENT.includes(appareil.toLowerCase()) ? 'laurent' : 'equipe';
const now = DateTime.now().setZone('Europe/Paris').setLocale('fr');
const lieu = String(b.lieu || '').split('\n').map(s => s.trim()).filter(Boolean).join(', ');
const vide = note.replace(/[^\p{L}\p{N}]/gu, '').length < 4;
const qui = auteur === 'laurent' ? `Laurent Bannière, le gérant` : `un technicien de l'équipe (${appareil})`;
const system = [
  `Tu ranges les mémos vocaux dictés sur iPhone chez ClimatPro.`,
  `Contexte : Laurent Bannière est gérant de ClimatPro (climatisation et pompes à chaleur sur la Côte d'Azur, techniciens Christophe et Axel) et de la holding KLB (SCI LARENA, SCI B4 Azur, immobilier, placements).`,
  `Vocabulaire de Laurent : quand il dit ClimatPro ou les techniciens ClimatPro, il parle de toute l'équipe. Quand il nomme Christophe ou Axel, le mémo concerne cette personne. Ce qui est pour lui seul, il le dit (pour moi, moi seul, à moi de...).`,
  `Réponds UNIQUEMENT par un objet JSON, sans texte autour, avec ces clés :`,
  `- type : TACHE (une action concrète à faire), IDEE (une idée, une piste, un projet à creuser, sans action immédiate), NOTE (une information à garder sur un client ou un chantier), DEVIS (un devis à faire ou un besoin de chiffrage).`,
  `- domaine : EQUIPE par défaut pour tout ce qui touche au métier et au terrain de ClimatPro, même dicté par Laurent : matériel, pièces ou filtres à prendre, commander ou récupérer, chantiers, interventions, entretiens, dépannages, client à recontacter pour une intervention, info technique, tout mémo qui parle des techniciens ClimatPro, de Christophe ou d'Axel. CLIMATPRO (c'est-à-dire Laurent ClimatPro, réservé au gérant) uniquement pour la gestion : devis et chiffrages, relances commerciales ou de paiement, factures, comptabilité, banque, administratif, RH et salaires, prix et négociations avec les fournisseurs, stratégie de l'entreprise, ou quand Laurent dit explicitement que c'est pour lui. En cas de doute entre EQUIPE et CLIMATPRO, choisis EQUIPE. HOLDING (KLB, SCI, immobilier, investissements, banque et comptable de la holding), PERSO (famille, maison, piscine, loisirs, santé, voiture perso, achats perso).`,
  `- destinataire : CHRISTOPHE ou AXEL si le mémo vise nommément cette personne, EQUIPE s'il vise les techniciens ou toute l'équipe, LAURENT seulement si Laurent dit explicitement que c'est pour lui, sinon null.`,
  `- client : nom du client ClimatPro tel que dicté (nom de famille, société, résidence), sinon null. Jamais Laurent, Sophie, Christophe ou Axel. Si le mémo dit seulement "ce client", "lui", "ici" sans nom, mets null.`,
  `- titre : reformulation courte et claire, verbe à l'infinitif pour une tâche, 70 caractères maximum. Ne mets PAS le nom du client dans le titre, il est ajouté à part.`,
  `- echeance : date au format AAAA-MM-JJ si une date ou un délai est dit (demain, lundi, avant la fin du mois...), calculée à partir de la date du jour fournie, sinon null.`,
  `- urgent : true seulement si l'urgence est dite explicitement, sinon false.`,
  `- resume : le mémo reformulé proprement, fidèle, sans rien ajouter, sans interpréter ni supposer la raison. Si le mémo fait moins de 12 mots, le résumé est simplement le mémo avec les fautes de dictée corrigées, rien de plus.`,
  `- confiance : HAUTE si le sens du mémo et son rangement (type et domaine) sont évidents. BASSE si le mémo est ambigu, trop court pour savoir ce qu'il faut en faire, ou si tu dois deviner (exemple : "Belle-mère Renault pompe à chaleur" = BASSE, on ne sait pas si c'est un prospect ou une info perso). Hésiter entre EQUIPE et CLIMATPRO ne rend pas la confiance BASSE : choisis EQUIPE.`,
  `- theme : ENTRETIEN (entretien, maintenance, nettoyage, révision, contrat ou visite d'entretien à proposer ; "relancer un client pour un entretien" = ENTRETIEN), RELANCE (relancer un client sur un devis ou une réponse attendue, hors entretien), DEPANNAGE (panne, fuite, code erreur, réparation), COMMANDE (matériel ou pièce à commander, acheter ou récupérer), sinon null.`,
  `Corrige les fautes de dictée évidentes. En cas de doute entre TACHE et IDEE, choisis TACHE si une action concrète est dite. Mieux vaut confiance BASSE qu'un rangement deviné.`
].join('\n');
const user = 'Date du jour : ' + now.toFormat('cccc dd LLLL yyyy') + ' (' + now.toFormat('yyyy-MM-dd') + ')\nAuteur : ' + qui + '\nLieu : ' + (lieu || 'inconnu') + '\nMémo : ' + note;
return [{ json: {
  note, appareil, auteur, lieu, vide,
  lat: b.lat || null, lon: b.lon || null,
  date: String(b.date || now.toFormat('dd/MM/yyyy HH:mm')),
  requete: { model: 'claude-haiku-4-5-20251001', max_tokens: 500, system, messages: [{ role: 'user', content: user }] }
} }];

const p = $('Preparer').first().json;
const r = $input.first().json || {};
let txt = '';
try { txt = (r.content || []).map(x => x.text || '').join(''); } catch (e) {}
let c = null;
try { const m = txt.match(/\{[\s\S]*\}/); c = JSON.parse(m ? m[0] : txt); } catch (e) { c = null; }

// Projets et sections Todoist (le projet climatpro s'appelle "Laurent ClimatPro" : reserve au gerant)
const P = { climatpro: '6hh423vJrW7RvQQg', equipe: '6hh423vw4vGgHFPw', holding: '6hh423wC29ffmXQp', perso: '6hh423vGr88f287j', idees: '6hhwGHjgC54vV2xr' };
const S = { cpAFaire: '6hh4246PVq2H9Fp8', cpDevis: '6hh4248WJ2ppj3M8', ideeCp: '6hhwGJMmm2rRX82J', ideeHolding: '6hhwGJMwRjxcjRwr', ideePerso: '6hhwGJMrrcJWGv8r' };
const NOM_LAURENT = 'Laurent ClimatPro';

const up = v => String(v || '').trim().toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const n = s => String(s || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
let type = c ? up(c.type) : '';
if (!['TACHE', 'IDEE', 'NOTE', 'DEVIS'].includes(type)) type = 'A_QUALIFIER';
let dom = c ? up(c.domaine) : '';
if (!['CLIMATPRO', 'EQUIPE', 'HOLDING', 'PERSO'].includes(dom)) dom = 'CLIMATPRO';
// Destinataire : Laurent seulement s'il l'a dit ; un technicien nomme ou les techniciens = Equipe
const dst = c ? up(c.destinataire) : '';
if (dst === 'LAURENT') { if (dom === 'EQUIPE') dom = 'CLIMATPRO'; }
else {
  if (['CHRISTOPHE', 'AXEL', 'EQUIPE'].includes(dst) && dom === 'CLIMATPRO') dom = 'EQUIPE';
  // Filet de securite : un memo terrain (entretien, depannage, commande) va toujours a l'equipe
  if (dom === 'CLIMATPRO' && c && ['ENTRETIEN', 'DEPANNAGE', 'COMMANDE'].includes(up(c.theme))) dom = 'EQUIPE';
}
// Decision de Laurent (option B) : ses memos restent prives dans Laurent ClimatPro, commandes comprises.
// Il les partage en nommant le technicien (label christophe / axel) ou depuis le tableau de bord (bouton avatar).
if (p.auteur === 'laurent' && dom === 'EQUIPE') dom = 'CLIMATPRO';
const cl = c && c.client ? String(c.client).trim() : '';
const client = cl && !/^(null|none|aucun|inconnu|-)$/i.test(cl) ? cl : null;
const titre = String((c && c.titre) || p.note).slice(0, 120);
const resume = String((c && c.resume) || p.note);
const echeance = c && /^\d{4}-\d{2}-\d{2}$/.test(String(c.echeance || '')) ? String(c.echeance) : null;
const urgent = !!c && (c.urgent === true || String(c.urgent).toLowerCase() === 'true');
// Doute : Haiku n'a pas repondu, type inconnu, ou confiance BASSE
const douteux = !c || type === 'A_QUALIFIER' || up(c.confiance) === 'BASSE';
const laurent = p.auteur === 'laurent';
const typeFr = { TACHE: 'Tâche', IDEE: 'Idée', NOTE: 'Info', DEVIS: 'Devis à faire', A_QUALIFIER: 'Mémo à trier' }[type];

// Memo de Laurent avec un doute (sens incertain, ou pro qui pourrait etre perso) et sans client ni technicien nomme :
// Perso par defaut, le raccourci iPhone pose la question Pro ou perso
const persoPossible = !!c && (c.perso_possible === true || String(c.perso_possible).toLowerCase() === 'true');
const doutePersoPro = persoPossible && ['EQUIPE', 'CLIMATPRO'].includes(dom);
const question = laurent && (douteux || doutePersoPro)
  && !['CHRISTOPHE', 'AXEL', 'EQUIPE', 'LAURENT'].includes(dst) && !client && ['TACHE', 'NOTE', 'A_QUALIFIER'].includes(type);
if (question) dom = 'PERSO';

let projet = null, section = null, dest = 'Boîte de réception', prefixe = '', action = 'todoist';
const labels = ['memo'];
// Memo qui vise nommement un technicien : label a son nom (c'est ce label qui le rend visible a ce technicien)
if (dst === 'CHRISTOPHE' || dst === 'AXEL') labels.push(n(dst));
// Laurent qui parle aux techniciens ou a toute l'equipe : partage avec les deux
if (dst === 'EQUIPE' && laurent) labels.push('christophe', 'axel');
if (!laurent) {
  // Memo d'un technicien : toujours et uniquement dans Equipe ClimatPro
  projet = P.equipe; dest = 'Équipe ClimatPro';
  if (douteux) { prefixe = 'À trier : '; labels.push('a-trier'); }
  else {
    if (type === 'IDEE') prefixe = 'Idée : ';
    if (type === 'DEVIS') { prefixe = 'Devis : '; labels.push('devis'); }
    if (type === 'NOTE') { if (client) action = 'interfast'; else prefixe = 'Info : '; }
  }
} else if (question) {
  projet = P.perso; dest = 'Perso'; labels.push('pro-ou-perso');
} else if (douteux) {
  // Pas sur du rangement : Boite de reception, Laurent tranche
  prefixe = 'À trier : '; labels.push('a-trier'); dest = 'Boîte de réception';
} else if (type === 'IDEE') {
  projet = P.idees;
  section = dom === 'HOLDING' ? S.ideeHolding : dom === 'PERSO' ? S.ideePerso : S.ideeCp;
  dest = 'Idées / ' + (dom === 'HOLDING' ? 'Holding & SCI' : dom === 'PERSO' ? 'Perso' : 'ClimatPro');
} else if (type === 'DEVIS') {
  projet = P.climatpro; section = S.cpDevis; dest = NOM_LAURENT + ' / Devis à faire'; labels.push('devis');
} else {
  if (type === 'NOTE') { if (client) action = 'interfast'; else prefixe = 'Info : '; }
  if (dom === 'EQUIPE') { projet = P.equipe; dest = 'Équipe ClimatPro'; }
  else if (dom === 'HOLDING') { projet = P.holding; dest = 'Holding & SCI'; }
  else if (dom === 'PERSO') { projet = P.perso; dest = 'Perso'; }
  else { projet = P.climatpro; section = S.cpAFaire; dest = NOM_LAURENT; }
}
if (dst === 'CHRISTOPHE' || dst === 'AXEL') dest = dest + ' (pour ' + dst.charAt(0) + dst.slice(1).toLowerCase() + ')';
else if (dst === 'EQUIPE' && laurent && projet === P.climatpro) dest = dest + ' (partagé avec Christophe et Axel)';
else if (laurent && projet === P.climatpro) dest = dest + ' (privé)';

// Le client n'est ajoute au titre que s'il n'y figure pas deja
const clientDejaDansTitre = !!client && n(titre).includes(n(client));
const suffixeClient = client && !clientDejaDansTitre ? ' - ' + client : '';

const origine = 'Dicté le ' + p.date + (p.lieu ? ' à ' + p.lieu : '') + ' (' + p.appareil + ')';
const todoist = {
  content: prefixe + titre + suffixeClient,
  description: resume + '\n\n' + origine + '\nTexte dicté : ' + p.note,
  labels,
  priority: urgent ? 4 : 1
};
if (projet) todoist.project_id = projet;
if (section) todoist.section_id = section;
if (echeance) todoist.due_date = echeance;
const quand = echeance ? ' (pour le ' + echeance.split('-').reverse().join('/') + ')' : '';
const entete = question ? 'Pro ou perso ? En attendant > Perso' : douteux ? 'Pas sûr d\'avoir compris > ' + dest : typeFr + ' > ' + dest + quand;
const message = entete + '\n' + todoist.content;

// Si la note client ne peut pas aller dans Interfast
const todoistRattacher = { content: 'Note à rattacher : ' + titre + (client && !clientDejaDansTitre ? ' (' + client + ')' : ''), labels: ['memo', 'a-rattacher'], priority: 1, project_id: laurent ? P.climatpro : P.equipe };
if (laurent) todoistRattacher.section_id = S.cpAFaire;
const noteCrm = 'Mémo vocal du ' + p.date + ' (' + p.appareil + ')\n' + resume + '\n\nTexte dicté : ' + p.note;

return [{ json: {
  action, type, domaine: dom, client, titre, resume, echeance, auteur: p.auteur, douteux, question,
  todoist, message, todoist_rattacher: todoistRattacher, note_crm: noteCrm,
  dest_rattacher: laurent ? NOM_LAURENT : 'Équipe ClimatPro',
  haiku_ok: !!c
} }];

// Ajoute le label de theme (entretien, relance, depannage, commande) donne par Haiku
// Commande de materiel d'un technicien : Equipe ClimatPro / Commandes materiel (vue par Laurent et l'equipe)
// Commande de Laurent (option B) : Laurent ClimatPro, privee sauf label christophe / axel (partage depuis le tableau de bord)
// Sauf si le memo est en attente de la question Pro ou perso (il reste dans Perso)
// + Icone : l'objet du memo (cle objet de Haiku) est note dans la description Todoist ("Icône : mot"),
//   le tableau de bord affiche l'icone correspondante et la liste d'attente pour Codex se remplit toute seule
const r = JSON.parse(JSON.stringify($input.first().json));
let c = null;
try {
  const t = (($('Classer (Haiku)').first().json || {}).content || []).map(x => x.text || '').join('');
  const m = t.match(/\{[\s\S]*\}/);
  c = JSON.parse(m ? m[0] : t);
} catch (e) { c = null; }
const T = { ENTRETIEN: 'entretien', RELANCE: 'relance', DEPANNAGE: 'depannage', COMMANDE: 'commande' };
const cle = c ? String(c.theme || '').trim().toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '') : '';
const th = T[cle] || null;
if (th) {
  r.theme = th;
  if (r.todoist) r.todoist.labels = [...new Set([...(r.todoist.labels || []), th])];
  if (r.todoist_rattacher) r.todoist_rattacher.labels = [...new Set([...(r.todoist_rattacher.labels || []), th])];
}
if (th === 'commande' && r.action === 'todoist' && r.todoist && !r.question) {
  const t = r.todoist;
  const prive = r.auteur === 'laurent';
  t.project_id = prive ? '6hh423vJrW7RvQQg' : '6hh423vw4vGgHFPw';
  t.section_id = prive ? '6hh4246PVq2H9Fp8' : '6hjM3Rw4RPRw474w';
  t.labels = (t.labels || []).filter(l => !['a-trier', 'client-proche', 'devis'].includes(l));
  let base = String(t.content || '').replace(/^(À trier|Idée|Info|Devis) : /, '');
  if (r.client_proche) base = base.replace(' - ' + r.client_proche + ' ?', '');
  t.content = 'À commander : ' + base;
  const pour = ['christophe', 'axel'].filter(l => t.labels.includes(l)).map(l => l.charAt(0).toUpperCase() + l.slice(1));
  const ou = prive ? 'Laurent ClimatPro' + (pour.length ? ' (partagée avec ' + pour.join(' et ') + ')' : ' (privée)') : 'Équipe ClimatPro / Commandes matériel';
  r.message = 'Commande > ' + ou + '\n' + t.content;
}
// Objet du memo -> icone
let objet = c ? String(c.objet || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '') : '';
if (/^(null|none|aucun|-)?$/.test(objet) || objet.length < 2 || objet.length > 40) objet = '';
if (objet) {
  r.objet = objet;
  if (r.todoist) r.todoist.description = String(r.todoist.description || '') + '\n\nIcône : ' + objet;
  if (r.todoist_rattacher) r.todoist_rattacher.description = String(r.todoist_rattacher.description || '') + '\n\nIcône : ' + objet;
}
